@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
:root {
  --card-padding-y: 2.5rem; --layout-gap: 1.5rem; --background: #0f1117; --foreground: #e2e8f0; --card: #1a1d2e; --card-foreground: #f1f5f9; --popover: #1a1d2e; --popover-foreground: #f1f5f9; --secondary: #252840; --secondary-foreground: #e2e8f0; --muted: #252840; --muted-foreground: #94a3b8; --accent: #2a2d3e; --accent-foreground: #e2e8f0; --destructive: #f472b6; --success: #34d399; --warning: #f59e0b; --info: #818cf8; --border: #1e2235; --input: #2a2d3e; --primary: oklch(0.7 0.18 var(--accent-hue, 275)); --primary-foreground: oklch(0.205 0 0); --ring: oklch(0.7 0.18 var(--accent-hue, 275)); --chart-1: oklch(0.72 0.22 var(--accent-hue, 275)); --chart-2: #34d399; --chart-3: #f59e0b; --chart-4: #f472b6; --chart-5: #38bdf8;
}
.dark {
  --card-padding-y: 2.5rem; --layout-gap: 1.5rem; --background: #0f1117; --foreground: #e2e8f0; --card: #1a1d2e; --card-foreground: #f1f5f9; --popover: #1a1d2e; --popover-foreground: #f1f5f9; --secondary: #252840; --secondary-foreground: #e2e8f0; --muted: #252840; --muted-foreground: #94a3b8; --accent: #2a2d3e; --accent-foreground: #e2e8f0; --destructive: #f472b6; --success: #34d399; --warning: #f59e0b; --info: #818cf8; --border: #1e2235; --input: #2a2d3e; --primary: oklch(0.7 0.18 var(--accent-hue, 275)); --primary-foreground: oklch(0.205 0 0); --ring: oklch(0.7 0.18 var(--accent-hue, 275)); --chart-1: oklch(0.72 0.22 var(--accent-hue, 275)); --chart-2: #34d399; --chart-3: #f59e0b; --chart-4: #f472b6; --chart-5: #38bdf8;
}
/* App root — centered with max-width for slide-like presentation */
.pf-app-root {
  padding: 2rem;
  max-width: 64rem;
  margin: 0 auto;
}

/* Font */
.pf-card, .pf-table {
  font-family: 'Inter', ui-sans-serif, system-ui, sans-serif;
}

/* Card — generous horizontal padding for slide-like presentation */
.pf-card-header,
.pf-card-content {
  padding-left: 2rem;
  padding-right: 2rem;
}

/* Progress/Slider — dark navy tracks */
.pf-progress,
.pf-progress-track {
  background: #252840;
}
.pf-slider-track {
  background: #252840;
}
.pf-progress-target {
  background: #f1f5f9;
  opacity: 0.5;
}

/* Badge — tinted backgrounds, consistent border-radius */
.pf-badge {
  border-radius: 6px;
  font-weight: 600;
  font-size: 0.9rem;
  padding: 0.2em 0.6em;
}
.pf-badge-variant-default {
  color: oklch(0.78 0.15 var(--accent-hue, 275));
  background: oklch(0.72 0.22 var(--accent-hue, 275) / 0.12);
}
.pf-badge-variant-warning {
  color: #fcd34d;
  background: rgba(245, 158, 11, 0.12);
}
.pf-badge-variant-destructive {
  color: #f9a8d4;
  background: rgba(244, 114, 182, 0.12);
}

/* Table cells — taller rows, tabular numerals, dimmer number color */
.pf-table-cell {
  padding: 0.85rem 0.75rem;
  font-size: 0.9rem;
  font-variant-numeric: tabular-nums;
  color: #cbd5e1;
}

/* Table rows — subtle borders, accent hover */
.pf-table-row {
  border-color: #1e2235;
}
.pf-table-row:hover {
  background: oklch(0.72 0.22 var(--accent-hue, 275) / 0.06);
}

:root {
  --radius: 0; --card-padding-y: 0.75rem; --layout-gap: 0.5rem; --background: #3a6ea5; --foreground: #000000; --card: #d4d0c8; --card-foreground: #000000; --popover: #d4d0c8; --popover-foreground: #000000; --primary: #0a246a; --primary-foreground: #ffffff; --secondary: #d4d0c8; --secondary-foreground: #000000; --muted: #d4d0c8; --muted-foreground: #404040; --accent: #0a246a; --accent-foreground: #ffffff; --border: #808080; --input: #ffffff; --ring: #0a246a; --destructive: #800000; --success: #008000; --warning: #808000; --info: #000080; --chart-1: #000080; --chart-2: #008080; --chart-3: #800000; --chart-4: #808000; --chart-5: #800080; --font-sans: Tahoma, 'MS Sans Serif', Verdana, Geneva, sans-serif; --w2k-raised: inset -1px -1px 0 0 #0a0a0a, inset 1px 1px 0 0 #ffffff, inset -2px -2px 0 0 #808080, inset 2px 2px 0 0 #dfdfdf; --w2k-sunken: inset 1px 1px 0 0 #808080, inset -1px -1px 0 0 #ffffff, inset 2px 2px 0 0 #0a0a0a, inset -2px -2px 0 0 #dfdfdf; --w2k-pressed: inset 1px 1px 0 0 #0a0a0a, inset -1px -1px 0 0 #ffffff, inset 2px 2px 0 0 #808080, inset -2px -2px 0 0 #dfdfdf;
}
.dark {
  --radius: 0; --card-padding-y: 0.75rem; --layout-gap: 0.5rem; --background: #3a6ea5; --foreground: #000000; --card: #d4d0c8; --card-foreground: #000000; --popover: #d4d0c8; --popover-foreground: #000000; --primary: #0a246a; --primary-foreground: #ffffff; --secondary: #d4d0c8; --secondary-foreground: #000000; --muted: #d4d0c8; --muted-foreground: #404040; --accent: #0a246a; --accent-foreground: #ffffff; --border: #808080; --input: #ffffff; --ring: #0a246a; --destructive: #800000; --success: #008000; --warning: #808000; --info: #000080; --chart-1: #000080; --chart-2: #008080; --chart-3: #800000; --chart-4: #808000; --chart-5: #800080; --font-sans: Tahoma, 'MS Sans Serif', Verdana, Geneva, sans-serif; --w2k-raised: inset -1px -1px 0 0 #0a0a0a, inset 1px 1px 0 0 #ffffff, inset -2px -2px 0 0 #808080, inset 2px 2px 0 0 #dfdfdf; --w2k-sunken: inset 1px 1px 0 0 #808080, inset -1px -1px 0 0 #ffffff, inset 2px 2px 0 0 #0a0a0a, inset -2px -2px 0 0 #dfdfdf; --w2k-pressed: inset 1px 1px 0 0 #0a0a0a, inset -1px -1px 0 0 #ffffff, inset 2px 2px 0 0 #808080, inset -2px -2px 0 0 #dfdfdf;
}
/* Nothing in Windows 2000 has a rounded corner. `--radius: 0` handles most of
   it; this catches the utilities that hardcode a pill radius. Portal content
   (dialogs, tooltips, popovers) renders outside .pf-app-root, so match on the
   class prefix rather than descendants of the root. */
[class^="pf-"],
[class*=" pf-"] {
  border-radius: 0;
}

.pf-app-root {
  font-family: var(--font-sans);
  font-size: 12px;
  color: #000;
  padding: 0.75rem;
}

/* Cards read as raised panels. The ring utility would draw a rounded halo
   over the bevel, so drop it. */
.pf-card {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
  --tw-ring-shadow: 0 0 #0000;
  padding: 3px;
}
.pf-card-header,
.pf-card-content,
.pf-card-footer {
  padding-left: 0.75rem;
  padding-right: 0.75rem;
}
.pf-card-title {
  font-size: 12px;
  font-weight: 700;
}
.pf-card-description {
  font-size: 11px;
  color: #404040;
}

/* Buttons: raised until pressed, then the bevel inverts and the label
   nudges down and right — the detail that sells it. */
.pf-button {
  background: #d4d0c8;
  color: #000;
  border: none;
  box-shadow: var(--w2k-raised);
  font-size: 12px;
  font-weight: 400;
  min-height: 23px;
  padding: 0 12px;
  transition: none;
}
.pf-button:hover {
  background: #d4d0c8;
}
.pf-button:active:not(:disabled) {
  box-shadow: var(--w2k-pressed);
  padding-top: 2px;
  padding-left: 13px;
  padding-right: 11px;
}
.pf-button:focus-visible {
  outline: 1px dotted #000;
  outline-offset: -4px;
  --tw-ring-shadow: 0 0 #0000;
}
.pf-button-variant-default {
  background: #d4d0c8;
  color: #000;
  font-weight: 700;
}
.pf-button-variant-default:hover {
  background: #d4d0c8;
  color: #000;
}
.pf-button-variant-ghost:not(:hover),
.pf-button-variant-link {
  box-shadow: none;
  background: transparent;
}
.pf-button-variant-link {
  color: #0000ee;
  text-decoration: underline;
}

/* Text entry is sunken and white — the universal "you can type here" cue. */
.pf-input,
.pf-textarea,
.pf-select-trigger,
.pf-combobox-trigger,
.pf-native-select {
  background: #ffffff;
  color: #000;
  border: none;
  box-shadow: var(--w2k-sunken);
  font-size: 12px;
  padding-left: 4px;
  transition: none;
}
.pf-input:focus-visible,
.pf-textarea:focus-visible,
.pf-select-trigger:focus-visible,
.pf-combobox-trigger:focus-visible {
  box-shadow: var(--w2k-sunken);
  --tw-ring-shadow: 0 0 #0000;
}
.pf-checkbox,
.pf-radio-group-item {
  background: #ffffff;
  border: none;
  box-shadow: var(--w2k-sunken);
}
.pf-checkbox[data-checked],
.pf-checkbox[data-state="checked"] {
  background: #ffffff;
  color: #000;
}
.pf-switch {
  background: #ffffff;
  box-shadow: var(--w2k-sunken);
  border: none;
}
.pf-switch-thumb {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
}

/* Tables are list views: a sunken white well with raised column headers that
   look like the clickable sort buttons they are. */
.pf-table-container {
  background: #ffffff;
  box-shadow: var(--w2k-sunken);
  padding: 2px;
}
.pf-table {
  font-size: 12px;
}
.pf-table-head {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
  color: #000;
  font-size: 11px;
  font-weight: 400;
  text-transform: none;
  letter-spacing: normal;
  height: 22px;
}
.pf-table-cell {
  padding: 3px 6px;
  color: #000;
}
.pf-table-row {
  border-color: #d4d0c8;
}
.pf-table-row:hover {
  background: #0a246a;
  color: #ffffff;
}
.pf-table-row:hover .pf-table-cell {
  color: #ffffff;
}

/* Segmented progress — the chunky blue blocks marching across a sunken well.
   Progress nests .pf-progress inside .pf-progress, so the well is drawn on the
   outer element and the inner one is flattened out of the way. The variant
   class sits on the indicator itself, so the fill rules double up the class to
   outrank the flat-fill CSS that `gradient=False` emits. */
.pf-progress,
.pf-progress-track {
  background: #ffffff;
  box-shadow: var(--w2k-sunken);
  height: 20px;
  padding: 3px;
}
.pf-progress .pf-progress,
.pf-progress .pf-progress-track {
  background: transparent;
  box-shadow: none;
  height: 100%;
  padding: 0;
}
.pf-progress-indicator.pf-progress-variant-default,
.pf-progress-indicator.pf-progress-variant-success,
.pf-progress-indicator.pf-progress-variant-warning,
.pf-progress-indicator.pf-progress-variant-destructive,
.pf-progress-indicator.pf-progress-variant-info,
.pf-progress-indicator.pf-progress-variant-muted {
  background-color: transparent;
  background-image: repeating-linear-gradient(
    to right,
    currentColor 0 10px,
    transparent 10px 12px
  );
}
.pf-progress-indicator.pf-progress-variant-default { color: #0a246a; }
.pf-progress-indicator.pf-progress-variant-success { color: #008000; }
.pf-progress-indicator.pf-progress-variant-warning { color: #808000; }
.pf-progress-indicator.pf-progress-variant-destructive { color: #800000; }
.pf-progress-indicator.pf-progress-variant-info { color: #000080; }
.pf-progress-indicator.pf-progress-variant-muted { color: #808080; }
.pf-progress-label,
.pf-progress-value {
  font-size: 11px;
  color: #000;
}

.pf-slider-track {
  background: #ffffff;
  box-shadow: var(--w2k-sunken);
  height: 4px;
}
.pf-slider-range {
  background: #0a246a;
}
.pf-slider-thumb {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
  border: none;
  width: 11px;
  height: 21px;
}

/* Badges are tiny raised chips rather than pills. */
.pf-badge {
  background: #d4d0c8;
  color: #000;
  border: none;
  box-shadow: var(--w2k-raised);
  font-size: 11px;
  font-weight: 400;
  padding: 1px 7px;
}
.pf-badge-variant-default { color: #0a246a; font-weight: 700; }
.pf-badge-variant-success { color: #008000; }
.pf-badge-variant-warning { color: #808000; }
.pf-badge-variant-destructive { color: #800000; }
.pf-badge-variant-info { color: #000080; }

/* Notebook tabs — the active one sits proud of the strip. */
.pf-tabs-list {
  background: transparent;
  gap: 2px;
  padding: 0;
}
.pf-tabs-trigger {
  background: #d4d0c8;
  color: #000;
  box-shadow: var(--w2k-raised);
  font-size: 12px;
  padding: 3px 12px;
}
.pf-tabs-trigger[data-active] {
  background: #d4d0c8;
  font-weight: 700;
  padding-bottom: 5px;
}
.pf-tabs-content {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
  padding: 0.75rem;
}

/* Dialogs are windows: gray face, navy title bar via .pf-dialog-header. */
.pf-dialog-content,
.pf-alert-dialog-content,
.pf-popover-content,
.pf-hover-card-content,
.pf-dropdown-menu-content,
.pf-select-content,
.pf-combobox-content,
.pf-command-dialog {
  background: #d4d0c8;
  color: #000;
  border: none;
  box-shadow: var(--w2k-raised);
  padding: 3px;
  font-size: 12px;
}
.pf-dialog-header,
.pf-alert-dialog-header {
  background: linear-gradient(90deg, #0a246a 0%, #a6caf0 100%);
  color: #ffffff;
  padding: 3px 4px;
  margin: 0 0 6px;
}
.pf-dialog-title,
.pf-alert-dialog-title {
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
}
.pf-dropdown-menu-item:hover,
.pf-select-item[data-highlighted],
.pf-combobox-item[data-highlighted] {
  background: #0a246a;
  color: #ffffff;
}

/* The famous pale-yellow tooltip. */
.pf-tooltip-content {
  background: #ffffe1;
  color: #000;
  border: 1px solid #000;
  box-shadow: none;
  font-size: 11px;
  padding: 2px 4px;
}

/* Etched groove: a shadow line above a highlight line. */
.pf-separator {
  background: transparent;
  border-top: 1px solid #808080;
  border-bottom: 1px solid #ffffff;
  height: 2px;
}

.pf-alert {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
  border: none;
  padding: 0.75rem;
}

.pf-code,
.pf-kbd {
  font-family: 'Courier New', monospace;
  background: #ffffff;
  box-shadow: var(--w2k-sunken);
  border: none;
  color: #000;
}

/* ── Window chrome ────────────────────────────────────────────────────────
   Utility classes the theme brings with it. They only exist while this theme
   is applied, and compose onto ordinary components: a Row for the title bar,
   Spans for the buttons, a Div for the inset well. */

.pf-window {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
  padding: 3px;
}
.pf-title-bar {
  align-items: center;
  background: linear-gradient(90deg, #0a246a 0%, #a6caf0 100%);
  color: #ffffff;
  display: flex;
  font-weight: 700;
  justify-content: space-between;
  min-height: 22px;
  padding: 3px 3px 3px 6px;
}
.pf-title-bar > * {
  color: #ffffff;
}
.pf-title-bar-button {
  background: #d4d0c8;
  box-shadow: var(--w2k-raised);
  color: #000;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 700;
  height: 16px;
  min-width: 18px;
  margin-left: 2px;
}
.pf-menu-bar {
  background: #d4d0c8;
  display: flex;
  gap: 2px;
  padding: 2px 4px;
}
.pf-menu-bar > * {
  color: #000;
  font-size: 12px;
  padding: 2px 8px;
}
.pf-menu-bar > *:hover {
  background: #0a246a;
  color: #ffffff;
}
.pf-status-bar {
  background: #d4d0c8;
  display: flex;
  gap: 3px;
  padding: 2px;
}
.pf-status-segment {
  box-shadow: inset 1px 1px 0 0 #808080, inset -1px -1px 0 0 #ffffff;
  color: #000;
  flex: 1;
  font-size: 11px;
  padding: 2px 6px;
}
/* Sunken white well — wrap charts and lists in it the way Explorer does. */
.pf-inset {
  background: #ffffff;
  box-shadow: var(--w2k-sunken);
  padding: 6px;
}

.pf-progress-variant-default,
.pf-progress-variant-success,
.pf-progress-variant-warning,
.pf-progress-variant-destructive,
.pf-progress-variant-info,
.pf-slider-variant-default,
.pf-slider-variant-success,
.pf-slider-variant-warning,
.pf-slider-variant-destructive,
.pf-slider-variant-info { background-image: none; }
.pf-ring-variant-default { stroke: var(--primary); }
.pf-ring-variant-success { stroke: var(--success); }
.pf-ring-variant-warning { stroke: var(--warning); }
.pf-ring-variant-destructive { stroke: var(--destructive); }
.pf-ring-variant-info { stroke: var(--info); }

@import url('https://fonts.googleapis.com/css2?family=Comic+Neue:wght@400;500;600;700&display=swap');
